// Generated by scripts/prepare.mjs. App assets only; song data is managed in IndexedDB.
const PREFIX='prelude:'+self.registration.scope+':';
const CACHE=PREFIX+'3674cdb27337dd76';
const ASSETS=["./","./index.html","./styles.css","./main.js","./install.js","./views.js","./core.js","./score.js","./audio.js","./storage.js","./follower.js","./icons.js","./dialogs.js","./touch-loop.js","./crypto.js","./vault.js","./vault.json","./manifest.webmanifest","./icon.svg","./icon-192.png","./icon-512.png","./catalog.json"];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(ASSETS))));
self.addEventListener('activate',event=>event.waitUntil((async()=>{for(const key of await caches.keys())if(key.startsWith(PREFIX)&&key!==CACHE)await caches.delete(key);await self.clients.claim();})()));
self.addEventListener('fetch',event=>{const url=new URL(event.request.url),base=new URL(self.registration.scope);if(event.request.method!=='GET'||url.origin!==base.origin||!url.pathname.startsWith(base.pathname))return;const relative=url.pathname.slice(base.pathname.length);if(relative.startsWith('tracks/'))return;event.respondWith((async()=>{const cache=await caches.open(CACHE);if(relative==='catalog.json'||relative==='vault.json'){try{const res=await fetch(event.request);if(res.ok)await cache.put(event.request,res.clone());return res;}catch{const cached=await cache.match(event.request);return cached||new Response('Offline',{status:503});}}const cached=await cache.match(event.request,{ignoreSearch:true});if(cached)return cached;if(event.request.mode==='navigate')return await cache.match(new URL('./index.html',base))||fetch(event.request);return fetch(event.request);})());});
